competence_axes:['rolle_og_materialforstaelse','kropp_stemme_og_tilstedevaerelse','ensemblelytting','proveromsdisiplin','repetisjon_og_notatbearbeiding','grense_og_sikkerhetskommunikasjon'],
ideal_type_problems:[{id:'rollevalg',problem:'En kunstnerisk note krever et tydelig rollevalg uten å miste ensemblets timing.'},{id:'endret_blocking',problem:'Blocking endres sent og må integreres trygt og presist.'},{id:'intimitet',problem:'En scene krever fysisk nærhet og tydelige samtykke- og grenseavklaringer.'},{id:'understudy',problem:'En medspiller faller ut og materialet må rekalibreres.'},{id:'slitasje',problem:'Belastning over flere forestillinger påvirker kvalitet og fysisk kapasitet.'}],
