notes:['Shared canonical work world for Scenekunst; legacy `teater` role models are retained separately for compatibility.'],
work_life:{daily_work:['Forbereder og prøver rolle- eller bevegelsesmateriale mot én eksplisitt sceneversjon og registrerer hva noten faktisk endret.','Kalibrerer partnerarbeid, cues, fysisk belastning og samtykkepremisser før intensitet eller tempo økes.','Bærer avtalt materiale gjennom gjennomløp og forestilling samtidig som avvik og nye premisser logges for neste prøve.','Følger opp belastning, fravær og restitusjon med riktig handoff slik at privat informasjon ikke blir kunstnerisk valuta eller skjult personalsak.'],responsibilities:['rolle- og materialarbeid','partner- og ensemblelytting','note og repetisjon','cue og forestillingsgjennomføring','grensekommunikasjon og bærekraft'],work_environment:['Prøverom, bevegelsesrom, scene og garderobe med reell venting på regi/koreografi-avklaring, partner-samtykke, teknisk/HMS-avklaring, cue-handoff, fravær eller rettighetsklarering.'],status_position:['Tillit følger evnen til å være presis, mottakelig og repeterbar uten å gjøre smerte, lojalitet eller status til erstatning for samtykke, sikkerhet eller faktisk kunstnerisk avtale.'],workplaces:places.map(x=>x.id)},
career_path:{entry_from:['Avtalt utøverstilling eller oppdrag; Badge-progresjon alene gir ikke ansettelse eller rolle.'],progression_to:['Større kunstnerisk ansvar, cover-/ensembleansvar eller mer krevende utøveroppdrag når kompetanse og arbeidsgiverprosess er dokumentert.'],possible_promotions:['Ledende utøver, solistisk eller ensemblebærende ansvar innen eksplisitt kunstnerisk og arbeidsgivermessig mandat.','Repetitør-, bevegelses-, prøveleder- eller coveransvar når kompetanse, delegasjon og arbeidsavtale faktisk foreligger.'],possible_exits:['Regi/koreografi, dramaturgi, pedagogikk, casting eller annen scenekunstpraksis.','Produksjon, formidling, prosjektarbeid eller annet arbeid der utøvererfaring er relevant uten at det automatisk gir ny myndighet.'],career_risks:['Statuspress kan gjøre et nei dyrt og skjule smerte, uenighet eller manglende samtykke som profesjonalitet.','Utydelige noter, cue-versjoner eller cover-handoffs kan skape partnerfeil, ekstra belastning og forestillingsgjeld.']},
required_knowledge:{education_basis:['Rolle- og materialarbeid, stemme/kropp, ensemblepraksis, prøveetikk, samtykke, HMS, fysisk bærekraft, cue-forståelse, restitusjon og rettighetsgrunnlag.'],skills:['rolle_og_materialarbeid','partner_og_ensemblelytting','note_og_repetisjon','cue_og_forestilling','grense_og_samtykkekommunikasjon','belastning_restitusjon_og_handoff'],category_knowledge:['Hvordan kunstnerisk oppgave, kropp, partner, sceneversjon, cue, samtykke, sikkerhet, rettigheter og restitusjon må møtes i én sporbar utøverpraksis.'],history_go_badges:['scenekunst'],place_connections:places.map(x=>x.id),people_connections:actors.map(x=>x.id)},
authority_boundary:{may:['foresla_rolle_bevegelses_og_partnerlosninger_innen_kunstnerisk_oppgave','melde_grense_belastning_usikkerhet_og_be_om_retest','bekrefte_egen_note_og_cueforstaelse_og_be_om_en_lesbar_handoff','forenkle_egen_utførelse_innen_avtalt_ramme_nar_sikkerhet_eller_baerekraft_krever_det'],may_not:['love_ansettelse_eller_rolle_til_andre','overstyre_regi_eller_koreografi_uten_mandat','ignorere_samtykke_hms_eller_fysiske_grenser','endre_rettighetsbelagt_materiale_som_om_du_eier_det','behandle_medisinsk_eller_privat_informasjon_som_kunstnerisk_evidens']},
