const commonSummary=' Ensembleboken skal samtidig skille lest/prøvd, avtalt, betinget og forestillingsklar status for rolle, partner, belastning, cue og forestilling. Dermed kan senere endringer gjenåpne bare berørte ledd uten at tidligere observasjon, sceneversjon, samtykkepremiss, beslutningseier eller handoff forsvinner. Hver mail må gjøre synlig hva som faktisk er observert eller avtalt, hvem som må svare før neste statusendring, og hva resten av ensemblet skal beholde mens avklaringen pågår.';
const makeChoice=(d,positive)=>positive?{id:'A',label:`Sporbar ${d.competency.replaceAll('_',' ')} med eksplisitt premiss`,reply:`${d.good} Jeg oppdaterer ensemblebok, sceneversjon, partner-/belastningspremiss, beslutningseier og neste retest slik at kunstnerisk initiativ ikke blir lest som regi-, arbeidsgiver-, samtykke-, HMS-, medisinsk- eller rettighetsmyndighet.`,effect:1,tags:['sporbarhet','ensemble','grense'],feedback:`${d.good} Dette holder prøven og forestillingen i bevegelse samtidig som utøvere, partner, inspisient og kunstnerisk/teknisk linje kan se hva som er prøvd, avtalt, betinget og forestillingsklart. Når premisset endres blir rework avgrenset, og handoff kan skje uten å skjule samtykke, belastning, cue eller beslutningseier.`,effects:{stats:{quality:2,trust:2,risk:-2,energy:-1}}}:{id:'B',label:`Anta ${d.competency.replaceAll('_',' ')} og fyll handoff senere`,reply:`${d.bad} Jeg lar prøve- eller forestillingsfarten være styrende og kompletterer versjon, partnerpremiss, belastning eller cue-handoff senere dersom neste aktør oppdager et problem eller ber om avklaring.`,effect:-1,tags:['statuspress','versjonsgjeld','risiko'],feedback:`${d.bad} Det kan spare tid nå, men flytter usikkerhet og risiko til partner, ensemble, inspisient eller egen kropp. Når et premiss endres blir det uklart hvilken versjon som gjaldt, hvem som faktisk samtykket til hva, og hvilke deler som må prøves eller avklares på nytt.`,effects:{stats:{status:1,quality:-2,trust:-2,risk:3}}};
const mails=defs.map((d,idx)=>{const m={id:d.id,mail_type:d.type,mail_family:typeFamily[d.type],role_scope:ROLE,phase:idx<5?'forenoon':idx<10?'workday':'late_workday',day_phase:idx<5?'morning':'afternoon',priority:150-idx,from:d.from,people_ref:d.person,person_id:d.person,place_id:d.place,subject:d.subject,summary:d.specific+commonSummary,situation:[d.specific,'Utøverens faglige initiativ er ikke i seg selv arbeidsgivermyndighet, regi/koreografi-mandat, partnerens samtykke, HMS/medisinsk godkjenning eller rettighetsfullmakt.','Neste steg må ha eksplisitt sceneversjon, premiss og eier og kunne gjenåpnes av ny dokumentert informasjon uten at tidligere observasjon eller partneravtale slettes.'],task_domain:ROLE,competency:d.competency,pressure:'kunstnerisk_og_forestillingstempo_vs_sporbar_note_grense_og_handoff',choice_axis:'sann_ensembleversjon_og_bounded_rework_vs_statuspress_og_skjult_gjeld',consequence_axis:'baerekraftig_repeterbar_forestilling_vs_partner_cue_og_belastningsgjeld',narrative_arc:d.id.replace('utover_',''),situated_audience_id:d.type==='knowledge'?'historisk_scenekunstkontekst':'utover_ensemble_og_arbeidsrelasjon',choices:[makeChoice(d,true),makeChoice(d,false)]};if(d.type==='knowledge'){m.interaction_mode='task';m.task_contract={task_id:'scenekunst_utoving_og_ensemble_history_go_edith_roger',completion_rule:'history_go_payload_completed',failure_rule:'remain_open',evidence_refs:['data/people/litteratur/oslo/nationaltheatret/edith_roger.json','data/places/scenekunst/oslo/places_scenekunst/nationaltheatret.json']};m.task_payload={task_kind:'history_go_person',target_type:'person',person_id:'edith_roger',completion_mode:'read_profile',title:'Les Edith Roger som historisk utøver- og ensemblesammenheng',description:'Noter ett spørsmål om hvordan sceneinstruksjon, ensemble, rollepraksis og institusjonelle vilkår påvirket hverandre uten å gjøre historien til fasit for dagens casting, samtykke, HMS eller kunstneriske metode.',return_context:{source:'civication',mail_id:d.id,role_scope:ROLE}}}return m});
const mailByType=Object.fromEntries(TYPES.map(t=>[t,mails.filter(m=>m.mail_type===t)]));
