const mailPlan={schema:'civication_mail_plan_v1',version:1,id:`${ROLE}_foundation_v1`,category:'scenekunst',role_scope:ROLE,title:'Utøving og ensemble',description:'Seksten steg gjennom samme utøverforløp fra første rolle- og partnerprøve til note, cue, fravær/cover, forestilling, belastningsoppfølging og sen konsekvens.',arc:{from:'Ny utøverfunksjon uten felles sannhetskilde for sceneversjon, note, partnerpremiss, cue og belastning.',to:'Utøver som bærer presis og bærekraftig ensemblepraksis gjennom press uten å låne myndighet fra arbeidsgiver, regi/koreografi, partner, HMS, medisin eller rettighet.',core_questions:['Hva er bare lest eller prøvd, hva er faktisk avtalt, og hva er forestillingsklart?','Hvem eier neste kunstneriske, partner-, cue-, HMS- eller bemanningsavklaring?','Hvilke ledd må retestes når note, partner, rom, cue eller belastning endres?']},situated_audience_contract:{no_global_score:true,audiences:['ensemble_og_partnere','regi_og_koreografi','inspisient_og_scene','arbeidsgiver_og_hms','privat_restitusjon'],rule:'Standing er bundet til konkret arbeidsrelasjon og leveranse; den skaper aldri global score, casting/ansettelse, regi/koreografi-mandat, partnerens samtykke, HMS/medisinsk godkjenning eller rettighetsfullmakt.'},outcome_rules:{promoted:{completion_ratio_gte:1,score_gte:2,strikes_lte:0},fired:{stability_values:['FIRED'],strikes_gte:3,score_lte:-3},stagnated:{autonomy_delta:-10,stability:'STAGNATED',add_branch_flags:['career_stagnated','utover_uten_sporbar_ensembleversjon']}},sequence:sequenceTypes.map((t,i)=>({step:i+1,type:t,phase:phaseFor(i),step_goal:stepGoal(t),allowed_families:[typeFamily[t]],fallback_types:[]}))};

