const manifestPath=path.join(ROOT,'data/Civication/roleModels/manifest.json');const manifest=JSON.parse(fs.readFileSync(manifestPath,'utf8'));if(!manifest.files.includes(MODEL)){manifest.files.push(MODEL);manifest.files.sort()}fs.writeFileSync(manifestPath,JSON.stringify(manifest,null,2)+'\n');

const report=`# Scenekunst — Utøving og ensemble prerequisites source-first\n\n## Scope\nThis materialization closes the current authored prerequisite debt for \`${KEY}\`. It is **not Role World completion** and it creates no new runtime.\n\n## Existing source foundation\n- Canonical Scenekunst badge/career evidence remains the source boundary.\n- The pre-existing role model already defined performer competence axes and core authority boundaries.\n- The pre-existing work grammar already defined role/material, rehearsal, ensemble, performance and self-management work loops.\n- This pass expands those sources into a complete, role-owned prerequisite package rather than inventing a parallel career.\n\n## Materialized work world\n- Four fictional scenario actors: Sara (skuespiller), Malik (danser/bevegelsespartner), Ingeborg (inspisient), Leo (understudy/cover).\n- Four role-owned work surfaces: prøverom/rollelogg, bevegelsesrom/grenselogging, scene/cue/ensembleposisjon, garderobe/restitusjonsflate.\n- Persistent object: \`ensemblebok_note_og_belastningslogg\`.\n- Rhythm: forbered → prøv → note → waiting/venting → partner/regi/HMS-avklaring → handoff → gjennomløp/forestilling → effektkontroll → restitusjon → bounded rework.\n- Fifteen authored mails across all nine required mail types, with a deterministic 16-step plan and no generic fallback.\n- Bounded History Go affordance: Edith Roger / Nationaltheatret is used to formulate a historical performer/ensemble question, never as authority for present-day casting, artistic method, consent, HMS or rights.\n\n## Authority boundary\nThe performer may interpret, propose, set personal boundaries, request retest and confirm own cue/note understanding. The role may not assign employment or roles, override directing/choreography without mandate, presume partner consent, bypass HMS/physical boundaries, treat medical/private information as artistic evidence or alter rights-protected material as owner.\n\n## Cross-role\nReadiness remains \`not_required_for_rollout\`. No shared-work object or cross-role runtime is materialized here.\n\n## Quality gate\n29/30 before ordinary exact-head PR browser/boot CI. The withheld point is intentionally reserved for the independent exact-head browser/boot gate after permanent materialization.\n`;
fs.mkdirSync(path.dirname(path.join(ROOT,REPORT)),{recursive:true});fs.writeFileSync(path.join(ROOT,REPORT),report);

const test=`const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');\nconst R=path.resolve(__dirname,'..'),read=p=>JSON.parse(fs.readFileSync(path.join(R,p))),KEY='${KEY}',ROLE='${ROLE}',MODEL='${MODEL}',GRAMMAR='${GRAMMAR}',PLAN='${PLAN}',TYPES=${JSON.stringify(TYPES)},ACTORS=${JSON.stringify(actors.map(x=>x.id))},PLACES=${JSON.stringify(places.map(x=>x.id))};\nconst g=read(GRAMMAR);assert.equal(g.persistent_work_object_contract.id,'ensemblebok_note_og_belastningslogg');assert.match(g.rhythm_contract.loop,/waiting|venting/i);assert.deepEqual(g.actor_grammar.map(x=>x.id),ACTORS);assert.deepEqual(g.place_grammar.map(x=>x.id),PLACES);assert.ok(g.knowledge_dependencies.some(x=>x.id==='history_go_scenekunst_edith_roger_nationaltheatret_utoverblikk'));assert.deepEqual(g.mail_generation_contract.required_mail_types,TYPES);assert.equal(g.day_one_contract.entry,'appointment_required');assert.match(g.authority_boundary.may_not.join(' '),/samtykke|hms|fysiske/i);assert.match(g.authority_boundary.may_not.join(' '),/regi|koreografi/i);assert.match(g.authority_boundary.may_not.join(' '),/rettighet/i);assert.equal(read('data/Civication/roleModels/manifest.json').files.filter(x=>x===MODEL).length,1);\nconst model=read(MODEL);assert.deepEqual(model.work_life.workplaces,PLACES);assert.deepEqual(model.related_people.map(x=>x.id),ACTORS);for(const p of model.related_people){assert.equal(p.fictional,true);assert.equal(p.fictional_scenario_actor,true);assert.equal(p.canonical_person_ref,null);assert.ok(p.workplace_ids.length===1);assert.ok(p.function.length>=220);assert.ok(p.authority_relation.length>=220)}assert.ok(model.career_path.possible_promotions.length>=2);assert.ok(model.career_path.possible_exits.length>=2);assert.ok(model.required_knowledge.history_go_badges.includes('scenekunst'));\nconst plan=read(PLAN);assert.equal(plan.id,ROLE+'_foundation_v1');assert.equal(plan.sequence.length,16);assert.deepEqual(plan.sequence.map(x=>x.type),${JSON.stringify(sequenceTypes)});for(const[i,s]of plan.sequence.entries()){assert.equal(s.step,i+1);assert.deepEqual(s.fallback_types,[]);assert.equal(s.allowed_families.length,1)}for(const x of ['promoted','fired','stagnated'])assert.ok(plan.outcome_rules[x]);\nconst C={job:4,people:4,conflict:1,story:1,event:1,micro:1,followup:1,knowledge:1,consequence:1},ids=new Set(),subjects=new Set();for(const type of TYPES){const c=read('data/Civication/mailFamilies/scenekunst/'+type+'/'+ROLE+'_'+type+'.json'),ms=c.families.flatMap(f=>f.mails||[]),labels=[];assert.equal(c.schema,'civication_mail_family_catalog_v1');assert.equal(c.mail_type,type);assert.equal(ms.length,C[type]);for(const x of ms){assert.ok(!ids.has(x.id));assert.ok(!subjects.has(x.subject));ids.add(x.id);subjects.add(x.subject);assert.ok(x.summary.length>=320);assert.equal(x.situation.length,3);assert.equal(x.choices.length,2);for(const q of x.choices){labels.push(q.label);assert.ok(q.reply.length>=150);assert.ok(q.feedback.length>=220);assert.ok(Object.keys(q.effects.stats).length>=3)}}assert.equal(new Set(labels).size,labels.length)}assert.equal(ids.size,15);\nconst k=read('data/Civication/mailFamilies/scenekunst/knowledge/'+ROLE+'_knowledge.json').families[0].mails[0];assert.equal(k.place_id,'nationaltheatret');assert.equal(k.task_payload.person_id,'edith_roger');assert.equal(k.task_contract.completion_rule,'history_go_payload_completed');for(const r of k.task_contract.evidence_refs)assert.ok(fs.existsSync(path.join(R,r)),r);\nconst pack=read('data/Civication/rolePackIndex.json').roles.find(x=>x.category==='scenekunst'&&x.role_scope===ROLE);assert.equal(pack.status,'complete_reference_v2');const career=read('data/Civication/careerGameplayMatrix.json').worlds.find(x=>x.key===KEY);assert.equal(career.status,'playable');assert.equal(career.audit.runtime_gate,true);assert.deepEqual(career.audit.missing_components,[]);\nconst rr=read('data/Civication/roleWorldRolloutReadiness.json'),ready=rr.roles.find(x=>x.key===KEY);assert.equal(ready.classification,'rollout_ready');assert.equal(ready.role_world_status,'role_world_not_started');for(const d of ['people_places_integrity','persistent_work_object','rhythm_waiting_handoff_rework','history_go_affordance','situated_reputation'])assert.equal(ready.dimensions[d].status,'foundation_ready',d);assert.deepEqual(ready.authored_work_required,[]);assert.equal(ready.cross_role.need,'not_required_for_rollout');assert.ok(rr.rollout_queue.some(x=>x.key===KEY));\nconst sp=read('data/Civication/scenarioPeople/generated/scenekunst.json'),fp=new Set(Object.values(sp.people_pool||{}).flat().map(x=>x.person_id));for(const id of ACTORS)assert.ok(!fp.has(id));const sf=fs.readFileSync(path.join(R,'${REPORT}'),'utf8');assert.match(sf,/not Role World completion/i);assert.match(sf,/ensemblebok_note_og_belastningslogg/);assert.match(sf,/not_required_for_rollout/);assert.match(sf,/29\\/30/);console.log('Civication Scenekunst Utoving og ensemble prerequisites: OK');\n`;
fs.writeFileSync(path.join(ROOT,TEST),test);
console.log(JSON.stringify({role:KEY,actors:actors.length,places:places.length,mails:mails.length,sequence:mailPlan.sequence.length,persistent_work_object:grammar.persistent_work_object_contract.id},null,2));
